// General power-of-2 base conversion (port of sipa's bech32 reference convertbits).
// Uses plain JS arrays and numbers only (no Uint8Array/DataView).

export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  const max_acc = (1 << (frombits + tobits - 1)) - 1;
  for (const value of data) {
    if (value < 0 || (value >> frombits) !== 0) {
      return null;
    }
    acc = ((acc << frombits) | value) & max_acc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }
  if (pad) {
    if (bits > 0) {
      ret.push((acc << (tobits - bits)) & maxv);
    }
  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv) !== 0) {
    return null;
  }
  return ret;
}

