// Segwit address encoder/decoder, ported from sipa's Python bech32 reference implementation.
// Pure ESM, no dependencies, plain arrays only (no Uint8Array/DataView).

import { bech32Encode, bech32Decode } from './bech32.mjs';
import { convertbits } from './convertbits.mjs';

// Internal decode helper: returns [witver, witprog] or [null, null] on failure.
function decodeSegwit(hrp, addr) {
    const [hrpgot, data, spec] = bech32Decode(addr);
    if (hrpgot !== hrp || data === null) {
        return [null, null];
    }
    const decoded = convertbits(data.slice(1), 5, 8, false);
    if (decoded === null || decoded.length < 2 || decoded.length > 40) {
        return [null, null];
    }
    if (data[0] > 16) {
        return [null, null];
    }
    if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
        return [null, null];
    }
    if ((data[0] === 0 && spec !== 'bech32') || (data[0] !== 0 && spec !== 'bech32m')) {
        return [null, null];
    }
    return [data[0], decoded];
}

// Encode a segwit address. Returns the address string, or null when invalid.
export function encodeSegwit(hrp, witver, witprog) {
    const spec = witver === 0 ? 'bech32' : 'bech32m';
    const data = convertbits(witprog, 8, 5);
    if (data === null) {
        return null;
    }
    const ret = bech32Encode(hrp, [witver, ...data], spec);
    const [decodedVer, decodedProg] = decodeSegwit(hrp, ret);
    if (decodedVer === null || decodedProg === null) {
        return null;
    }
    return ret;
}

