// Core bech32/bech32m primitives (port of sipa's Python reference).
// Plain arrays and numbers only; no Uint8Array/DataView.

export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

const GENERATORS = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

const BECH32_CONST = 1;
const BECH32M_CONST = 0x2bc830a3;

export function bech32Polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >>> 25;
    chk = (((chk & 0x1ffffff) << 5) ^ value) >>> 0;
    for (let i = 0; i < 5; i++) {
      if ((top >>> i) & 1) {
        chk = (chk ^ GENERATORS[i]) >>> 0;
      }
    }
  }
  return chk;
}

export function bech32HrpExpand(hrp) {
  const ret = [];
  for (let i = 0; i < hrp.length; i++) {
    ret.push(hrp.charCodeAt(i) >>> 5);
  }
  ret.push(0);
  for (let i = 0; i < hrp.length; i++) {
    ret.push(hrp.charCodeAt(i) & 31);
  }
  return ret;
}

export function bech32VerifyChecksum(hrp, data) {
  const chk = bech32Polymod(bech32HrpExpand(hrp).concat(data));
  if (chk === BECH32_CONST) {
    return 'bech32';
  }
  if (chk === BECH32M_CONST) {
    return 'bech32m';
  }
  return null;
}

export function bech32CreateChecksum(hrp, data, spec) {
  const values = bech32HrpExpand(hrp).concat(data);
  const constVal = spec === 'bech32m' ? BECH32M_CONST : BECH32_CONST;
  const polymod = (bech32Polymod(values.concat([0, 0, 0, 0, 0, 0])) ^ constVal) >>> 0;
  const ret = [];
  for (let i = 0; i < 6; i++) {
    ret.push((polymod >>> (5 * (5 - i))) & 31);
  }
  return ret;
}

export function bech32Encode(hrp, data, spec) {
  const combined = data.concat(bech32CreateChecksum(hrp, data, spec));
  let ret = hrp + '1';
  for (const d of combined) {
    ret += CHARSET[d];
  }
  return ret;
}

export function bech32Decode(bech) {
  const invalid = [null, null, null];
  if (typeof bech !== 'string') {
    return invalid;
  }
  let hasLower = false;
  let hasUpper = false;
  for (let i = 0; i < bech.length; i++) {
    const code = bech.charCodeAt(i);
    if (code < 33 || code > 126) {
      return invalid;
    }
    if (code >= 97 && code <= 122) {
      hasLower = true;
    }
    if (code >= 65 && code <= 90) {
      hasUpper = true;
    }
  }
  if (hasLower && hasUpper) {
    return invalid;
  }
  const bechLower = bech.toLowerCase();
  const pos = bechLower.lastIndexOf('1');
  if (pos < 1 || pos + 7 > bechLower.length || bechLower.length > 90) {
    return invalid;
  }
  const data = [];
  for (let i = pos + 1; i < bechLower.length; i++) {
    const idx = CHARSET.indexOf(bechLower[i]);
    if (idx === -1) {
      return invalid;
    }
    data.push(idx);
  }
  const hrp = bechLower.slice(0, pos);
  const spec = bech32VerifyChecksum(hrp, data);
  if (spec === null) {
    return invalid;
  }
  return [hrp, data.slice(0, -6), spec];
}

