// Manual replication of Python argparse for:
//   parser with options --a (str, required), --b (int, required), --c (str, required)
// Supports "--opt value" and "--opt=value" forms, plus -h/--help.

function getProg() {
  const script = process.argv[1];
  if (!script) return 'prog';
  // basename without depending on node:path semantics for either separator
  const parts = script.split('/');
  return parts[parts.length - 1] || 'prog';
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C`;
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// Python int() semantics: optional surrounding whitespace, optional +/- sign,
// decimal digits only.
function parsePythonInt(raw) {
  if (!/^\s*[+-]?\d+\s*$/.test(raw)) return null;
  const n = parseInt(raw, 10);
  if (Number.isNaN(n)) return null;
  return n;
}

const OPTION_NAMES = ['--a', '--b', '--c'];

export function parseArgs(argv) {
  const prog = getProg();
  const values = { a: undefined, b: undefined, c: undefined };
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp(prog);
      process.exit(0);
    }

    let name = null;
    let inlineValue = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        const candidate = token.slice(0, eq);
        if (OPTION_NAMES.includes(candidate)) {
          name = candidate;
          inlineValue = token.slice(eq + 1);
        }
      } else if (OPTION_NAMES.includes(token)) {
        name = token;
      }
    }

    if (name === null) {
      extras.push(token);
      i += 1;
      continue;
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
      i += 1;
    } else {
      const next = argv[i + 1];
      // argparse will not consume a following option-like token as a value
      if (next === undefined || (next.length > 1 && next.startsWith('-') && !/^[+-]?\d/.test(next))) {
        fail(prog, `argument ${name}: expected one argument`);
      }
      raw = next;
      i += 2;
    }

    const key = name.slice(2);
    if (key === 'b') {
      const n = parsePythonInt(raw);
      if (n === null) {
        fail(prog, `argument --b: invalid int value: '${raw}'`);
      }
      values.b = n;
    } else {
      values[key] = raw;
    }
  }

  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (values.c === undefined) missing.push('--c');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: values.a, b: values.b, c: values.c };
}

